def get_next_available_port():
    """
    Returns the next available port number.
    """
    for port in range(1024, 65535):
        if not os.name == 'nt' and port in [i for i in range(3000, 3020)]:
            continue
        try:
            with FileLock('/tmp/port_{0}.lock'.format(port)) as lock:
